                                                                 '#\n'
                                                                 '# For each participant, seed pool, and BA-defined '
                                                                 'target region, it builds\n'
                                                                 '# one multivariate FC fingerprint by concatenating '
                                                                 'every seed-to-target edge:\n'
                                                                 '#\n'
                                                                 '#     [seed_1->target_1, ..., seed_K->target_1,\n'
                                                                 '#      seed_1->target_2, ..., seed_K->target_M]\n'
                                                                 '#\n'
                                                                 '# Therefore:\n'
                                                                 '#     number of fingerprint features = N_seed_ROIs x '
                                                                 'N_target_ROIs_in_region\n'
                                                                 '#\n'
                                                                 '# The participant-by-participant neural similarity '
                                                                 'matrix is then computed\n'
                                                                 '# under multiple metrics, including Euclidean, '
                                                                 'Manhattan, cosine,\n'
                                                                 '# profile-correlation, Mahalanobis, and '
                                                                 'mean-FC-level similarity.\n'
                                                                 '#\n'
                                                                 '# Main inferential family\n'
                                                                 '# -----------------------\n'
                                                                 '# BH-FDR is applied separately within each:\n'
                                                                 '#\n'
                                                                 '#     movie x affective state x seed pool x neural '
                                                                 'similarity method\n'
                                                                 '#\n'
                                                                 '# across BA-defined target regions.\n'
                                                                 '#\n'
                                                                 '# An additional, stricter FDR column is also '
                                                                 'calculated across every\n'
                                                                 '# neural-method x target-region test within each:\n'
                                                                 '#\n'
                                                                 '#     movie x affective state x seed pool\n'
                                                                 '#\n'
                                                                 '# Optional leave-one-target-ROI-out stability '
                                                                 'analysis is run for significant\n'
                                                                 '# region-level AnnaK effects.\n'
                                                                 '#\n'
                                                                 '# Required pre-existing variables\n'
                                                                 '# -------------------------------\n'
                                                                 '# The script assumes the following objects already '
                                                                 'exist in the environment,\n'
                                                                 "# as in the user's current analysis "
                                                                 'notebook/script:\n'
                                                                 '#\n'
                                                                 '#     data_a\n'
                                                                 '#     data_b\n'
                                                                 '#     sub_list_a\n'
                                                                 '#     sub_list_b\n'
                                                                 '#     roi_df\n'
                                                                 '#     indi_sim_nn_state_fear\n'
                                                                 '#     indi_sim_annak_state_fear\n'
                                                                 '#     indi_sim_nn_state_valence\n'
                                                                 '#     indi_sim_annak_state_valence\n'
                                                                 '#\n'
                                                                 '# roi_df must contain the BA column specified by '
                                                                 'BA_COLUMN below. Atlas rows\n'
                                                                 '# are mapped to the 0-based data ROI axis robustly '
                                                                 'using ROI_num/ROI columns\n'
