                                                                 '# 0. Explicit Shen268 metadata loading\n'
                                                                 '# '
                                                                 '============================================================\n'
                                                                 'SCRIPT_DIR = Path(__file__).resolve().parent\n'
                                                                 'PROJECT_ROOT = next(\n'
                                                                 '    (parent for parent in SCRIPT_DIR.parents if '
                                                                 '(parent / "data").exists() and (parent / '
                                                                 '"results").exists()),\n'
                                                                 '    SCRIPT_DIR.parents[1],\n'
                                                                 ')\n'
                                                                 'DATA_ROOT = Path(os.environ.get("VISC_DATA_DIR", '
                                                                 'PROJECT_ROOT / "data")).expanduser()\n'
                                                                 'RESULTS_ROOT = Path(\n'
                                                                 '    os.environ.get("VISC_RESULTS_DIR", PROJECT_ROOT '
