                                                                 ').expanduser()\n'
                                                                 '\n'
                                                                 'SHEN268_CSV_PATH = str(DATA_ROOT / "shen268.csv")\n'
                                                                 '\n'
                                                                 'if not os.path.isfile(SHEN268_CSV_PATH):\n'
